import chess
import chess.engine
import json

CONFIG_FILE = "game/engine.json"

def cfg():
    return json.loads(open(CONFIG_FILE).read())

def engine():
    c = cfg()
    e = chess.engine.SimpleEngine.popen_uci(c["engine_path"])
    try:
        e.configure({"Skill Level": c["skill"]})
    except Exception:
        pass
    return e, chess.engine.Limit(depth=c["depth"], time=c["movetime_ms"] / 1000.0)

b = chess.Board("rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1")

e, lim = engine()
lim = chess.engine.Limit(time=5.0)
result = e.play(b, lim)
print("Best move:", result.move)
e.quit()
'"}

